CREATE OR REPLACE PROCEDURE sp(
    arg1 integer, 
    arg2 text, 
    arg3 text, 
    arg4 integer, 
    arg5 text, 
    arg6 integer
)
LANGUAGE plpgsql
AS $$
DECLARE
    state text := 'INIT';
    handled_row_count integer := 0;
    batch_size integer := 10;
    high_priority_seen boolean := false;
    current_threshold integer := arg1;
    row record;
BEGIN
    -- Determine mode based on threshold
    IF current_threshold < 3 THEN
        state := 'MINIMAL_PROCESS';
        FOR row IN
            SELECT "ResID", "ResName", "Address"
            FROM "Restaurant"
            WHERE "ResID" < arg1 AND "ResName" LIKE arg2
            ORDER BY "ResID"
        LOOP
            handled_row_count := handled_row_count + 1;

            IF row."ResID" > 25 THEN
                UPDATE "Restaurant"
                SET "ResName" = 'PROMOTED'
                WHERE "ResID" = row."ResID";
            ELSIF row."Address" = arg3 THEN
                DELETE FROM "Visits_Restaurant"
                WHERE "ResID" = row."ResID";
                DELETE FROM "Type_Of_Restaurant"
                WHERE "ResID" = row."ResID";
                DELETE FROM "Restaurant"
                WHERE "ResID" = row."ResID";
            ELSE
                UPDATE "Restaurant"
                SET "Address" = 'PENDING'
                WHERE "ResID" = row."ResID";
            END IF;

            IF handled_row_count >= batch_size THEN
                batch_size := batch_size + 5;
            END IF;
        END LOOP;

    ELSIF current_threshold < 8 THEN
        state := 'STANDARD_PROCESS';
        FOR row IN
            SELECT "StuID", "city_code", "LName"
            FROM "Student"
            WHERE "StuID" BETWEEN arg4 - 5 AND arg4 + 15
            ORDER BY "StuID"
        LOOP
            handled_row_count := handled_row_count + 1;

            IF row."city_code" = arg3 THEN
                UPDATE "Student"
                SET "Sex" = 'U'
                WHERE "StuID" = row."StuID";
            END IF;

            IF row."LName" = arg5 THEN
                UPDATE "Student"
                SET "city_code" = 'MATCHED'
                WHERE "StuID" = row."StuID";
            END IF;

            IF row."LName" LIKE 'ACTIVE%' THEN
                UPDATE "Student"
                SET "LName" = 'PROCESSED'
                WHERE "StuID" = row."StuID";
            ELSIF row."StuID" > arg4 + 5 THEN
                current_threshold := current_threshold + row."StuID";
            ELSIF row."LName" = 'EXPIRED' THEN
                DELETE FROM "Student"
                WHERE "StuID" = row."StuID";
            END IF;

            IF handled_row_count >= batch_size THEN
                batch_size := batch_size + 5;
            END IF;
        END LOOP;

    ELSIF current_threshold < 18 THEN
        state := 'ENHANCED_PROCESS';
        FOR row IN
            SELECT "ResTypeID"
            FROM "Restaurant_Type"
            WHERE "ResTypeID" > arg6 - 20
            ORDER BY "ResTypeID"
        LOOP
            handled_row_count := handled_row_count + 1;

            IF row."ResTypeID" < 50 THEN
                -- Low priority, do nothing
            ELSIF row."ResTypeID" < 150 THEN
                -- Medium priority
            ELSE
                high_priority_seen := true;
            END IF;

            UPDATE "Restaurant_Type"
            SET "ResTypeID" = row."ResTypeID" + 10
            WHERE "ResTypeID" = row."ResTypeID";

            IF handled_row_count >= batch_size THEN
                batch_size := batch_size + 5;
            END IF;
        END LOOP;

    ELSIF current_threshold < 25 THEN
        state := 'ARCHIVE_MODE';
        UPDATE "Restaurant"
        SET "Address" = 'ARCHIVED'
        WHERE "ResID" < arg1 AND "ResName" <> arg2;

    ELSIF current_threshold < 40 THEN
        state := 'CLEANUP_MODE';
        DELETE FROM "Student"
        WHERE "StuID" < arg4 AND "LName" = 'OBSOLETE';

    ELSE
        state := 'BOOST_MODE';
        UPDATE "Restaurant_Type"
        SET "ResTypeID" = arg6 + 100
